home=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow">17/7 Performance Gym · Rheinbach</p><h1>Dein Training.<span>Dein Gym.</span></h1><p class="lead">Inhabergeführt. Persönlich. Mit Platz für dein Training. Entdecke dein Warehouse Gym in Rheinbach – vom ersten Training bis zu deinem nächsten Ziel.</p><div class="actions">{button('Jetzt Mitglied werden','/mitglied-werden/')}{button('Das Gym kennenlernen','/studio/','secondary',False)}</div><p class="hero-note">Dein Tarif. Deine Angaben. Dein Vertrag als PDF.</p></div><div class="hero-photo">{img(ASSETS['hero'],eager=True,sizes='(max-width:650px) max(100vw, 100svh), max(50vw, 100svh)')}<span class="image-note">Echte Einblicke. Dein Studio in Rheinbach.</span></div></section><div class="quickfacts"><div class="wrap"><div class="fact"><strong>06–22 Uhr</strong><span>Täglich für dich geöffnet*</span></div><div class="fact"><strong>2</strong><span>Freihantelbereiche<br>für dein Training</span></div><div class="fact"><strong>26,99 €</strong><span>Standard pro Monat<br>12 Monate Laufzeit</span></div></div></div><section class="section"><div class="wrap"><div class="intro-grid"><div><p class="eyebrow">Kraft. Ausdauer. Dein Rhythmus.</p><h2>Mehr Raum für<br>dein nächstes Ziel.</h2></div><div><p>Langhantel oder Kraftgerät, Laufband oder freie Trainingsfläche: Im Performance Gym findest du die Ausstattung für deinen eigenen Weg. Ob du gerade einsteigst oder schon lange trainierst – lerne unser Studio und die Menschen dahinter kennen.</p>{textlink('Training & Ausstattung','/training/')}</div></div><div class="training-grid">'''
areas=[('01','Kraft & Freihanteln','Zwei Freihantelbereiche, Langhanteln, Kurzhanteln und Kraftgeräte. Raum, um konzentriert an deinen Zielen zu arbeiten.',GALLERY[1],'kraft'),('02','Cardio & Ausdauer','Laufbänder, Crosstrainer und Ergometer. Finde den Ausgleich oder bring Bewegung in deinen Alltag.',GALLERY[6],'cardio'),('03','Functional Training','Freie Trainingsflächen und Rigs für vielseitige Bewegungen. Gestalte dein Training so, wie es zu dir passt.',GALLERY[0],'functional')]
