home+='</div></div></section>'
home+=f'''<section class="split light"><div class="split-photo">{img(GALLERY[-1])}</div><div class="split-copy"><p class="eyebrow">Persönlich statt beliebig.</p><h2>Ein Gym mit<br>eigenem Charakter.</h2><p>Hohe Hallen, echte Trainingsflächen und ein Team vor Ort. Unser inhabergeführtes Studio verbindet den Charakter eines Warehouse Gyms mit einer persönlichen Atmosphäre.</p><p>Du findest uns in der Industriestraße in Rheinbach – auch aus Meckenheim und Euskirchen gut erreichbar.</p><div class="actions">{button('Schau dich um','/studio/','dark')}</div><div class="signature"><strong>17/7 Performance Gym</strong>Dein Training. Hier in Rheinbach.</div></div></section><section class="section"><div class="wrap price-band"><div><p class="eyebrow">Mitgliedschaften</p><h2>Dein Training.<br>Deine Entscheidung.</h2><p class="lead" style="margin-top:25px">12 Monate planen oder monatlich kündbar bleiben. Vergleiche unsere Tarife und finde heraus, was zu deinem Alltag passt.</p><div class="actions">{button('Alle Tarife vergleichen','/preise-aktionen/')}</div></div><div class="price-callout"><span class="eyebrow">Standard</span><div class="price-big">26,99 €<small>pro Monat · 12 Monate Laufzeit</small></div><p>Monatlich zahlbar. Zuzüglich einmalig 19,99 € für das E-Band. Keine Aufnahmegebühr.</p></div></div></section>'''+trial_band()
home+=f'''<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Menschen machen den Unterschied.</p><h2>Dein Team im Gym.</h2></div>{textlink('Alle kennenlernen','/unser-team/')}</div><div class="team-grid home-team">{''.join(person_card(p) for p in [TEAM[3],TEAM[0],TEAM[1]])}</div></div></section><section class="section compact"><div class="wrap faq-layout"><div><p class="eyebrow">Gut zu wissen</p><h2>Dein Einstieg.<br>Deine Fragen.</h2></div>{faq([CONTENT['draft_copy']['faq'][i] for i in [0,1,2,7]])}</div></section>'''
home += '<section class="section instagram-section" id="instagram" data-instagram-feed aria-labelledby="instagram-heading"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Aus unserem Gym</p><h2 id="instagram-heading">Training. Menschen.<br>Echte Einblicke.</h2></div><a class="text-link" href="https://www.instagram.com/17.7.performance.gym/" target="_blank" rel="noopener noreferrer">@17.7.performance.gym ↗</a></div><div class="instagram-feed-frame"><div class="instagram-feed-placeholder" aria-hidden="true"><span></span><span></span><span></span><span></span></div><p class="instagram-feed-status" data-feed-status role="status">Einblicke aus unserem Gym werden geladen …</p><!-- Elfsight Instagram Feed --><div class="elfsight-app-563dff4a-619d-4b7d-8355-b4e6426327b0" data-elfsight-app-lazy></div></div><p class="instagram-feed-note">Instagram-Feed, bereitgestellt von Elfsight. <a href="/datenschutzerklaerung/#instagram-feed">Datenschutzhinweise</a></p><noscript><p>Unsere aktuellen Beiträge findest du <a href="https://www.instagram.com/17.7.performance.gym/" target="_blank" rel="noopener noreferrer">direkt auf Instagram ↗</a>.</p></noscript></div></section>'
page('/','Performance Gym Rheinbach | Dein persönliches Warehouse Gym','Krafttraining, Cardio und Functional Training im inhabergeführten Performance Gym Rheinbach. Probetraining ohne Termin. Standard ab 26,99 € pro Monat.',home)
# Training
body=head('Training, das<br>zu dir passt.','Kraftgeräte, zwei Freihantelbereiche, Cardio und freie Trainingsflächen. Entdecke die Möglichkeiten in deinem Gym.','Training & Ausstattung',GALLERY[1],crumb='Training')+'<section class="section"><div class="wrap">'
for n,title,desc,photo,anchor in areas:
    extra={'kraft':'Trainiere mit freien Gewichten oder an geführten Geräten. Die beiden Freihantelbereiche bieten Platz für unterschiedliche Trainingsweisen.','cardio':'Wähle zwischen Laufband, Crosstrainer und Ergometer. Für dein Warm-up, eine Ausdauereinheit oder Bewegung zwischendurch.','functional':'Nutze die Rigs und freien Flächen für dein funktionelles Training. Du entscheidest, wie du deine Einheiten gestaltest.'}[anchor]
    body+=f'<article class="feature-row" id="{anchor}"><div class="feature-photo">{img(photo)}</div><div class="feature-copy"><p class="eyebrow">{n} / Dein Training</p><h2>{title}</h2><p>{extra}</p><div class="actions">{button('Beim Probetraining entdecken','/probetraining/','secondary')}</div></div></article>'
body+='</div></section>'+f'''<section class="section light" id="personal-training"><div class="wrap intro-grid"><div><p class="eyebrow">Persönlich an deinem Ziel arbeiten</p><h2>Personal Training.</h2></div><div><p>Du suchst eine individuelle Begleitung für dein Training? Lerne unsere Personal Trainer und ihre Schwerpunkte kennen. Leistungen und Termine besprichst du direkt mit dem Team.</p><div class="actions">{button('Personal Trainer kennenlernen','/unser-team/?filter=personal-trainers','dark')}</div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Einblicke aus dem Studio</p><h2>Training verbindet.</h2></div></div>{media('video')}</div></section>'''+trial_band()
page('/training/','Training & Ausstattung | Performance Gym Rheinbach','Kraftgeräte, zwei Freihantelbereiche, Cardio und Functional Training: Entdecke die Trainingsmöglichkeiten im Performance Gym Rheinbach.',body)
# Studio
body=head('Warehouse.<br>Persönlich. Rheinbach.','Echte Einblicke in dein Studio: Trainingshallen, Ausstattung und die Menschen hinter dem Performance Gym.','Das Gym',GALLERY[0],crumb='Das Gym')+f'''<section class="section"><div class="wrap intro-grid"><div><p class="eyebrow">Ein Ort für dein Training</p><h2>Viel Charakter.<br>Platz für dich.</h2></div><div><p>Ein inhabergeführtes Gym mit persönlicher Atmosphäre. Hier trainierst du zwischen Stahlträgern, Rigs und Kraftgeräten – mit Freiraum für deinen eigenen Rhythmus.</p><p>Komm vorbei und mach dir selbst ein Bild. Unser Team freut sich darauf, dich kennenzulernen.</p>{textlink('Lerne unser Team kennen','/unser-team/')}</div></div></section><section class="section compact" id="galerie"><div class="wrap"><div class="section-head"><div><p class="eyebrow">So sieht es bei uns aus</p><h2>Dein erster Einblick.</h2></div>{textlink('Zum 360°-Rundgang','/360-tour/')}</div>{gallery(GALLERY)}</div></section><section class="section"><div class="wrap visit-box"><div>{img(GALLERY[-1],cls='visit-photo')}</div><div class="visit-info"><p class="eyebrow">Industriestraße 32 a–e</p><h2>Mitten in<br>deinem Alltag.</h2><p class="muted">Trainiere in Rheinbach – mit kostenfreien Parkmöglichkeiten am Studio und regulären Öffnungszeiten von 06 bis 22 Uhr.</p><div class="actions">{button('Anfahrt & Kontakt','/contact/')}</div><p class="small muted" style="margin-top:18px">An gesetzlichen Feiertagen können die Zeiten abweichen.</p></div></div></section>'''+trial_band()
