# Memberships
body=head('Wähle deinen<br>Rhythmus.','12 Monate planen oder monatlich kündbar bleiben. Hier findest du unsere Mitgliedschaften und die ausgewiesenen Zusatzkosten.','Mitgliedschaften',crumb='Preise')+'<section class="section"><div class="wrap"><div class="plan-grid">'
for i,p in enumerate(CONTENT['facts']['membership_plans']):
    label=p['label'];num=p['monthly_eur'].replace('.',',');planid=p['id']
